<?php
declare(strict_types=1);
function require_idempotency_key(): string {$key=trim((string)($_SERVER['HTTP_IDEMPOTENCY_KEY']??''));if(!preg_match('/^[A-Za-z0-9._:-]{16,120}$/',$key))json_response(422,['success'=>false,'message'=>'A valid Idempotency-Key header is required.']);return $key;}
function begin_idempotent_request(string $scope,array $principal,array $payload): array {
    $key=require_idempotency_key();$hash=hash('sha256',json_encode($payload,JSON_UNESCAPED_SLASHES|JSON_UNESCAPED_UNICODE));$db=get_db();
    try{$stmt=$db->prepare('INSERT INTO idempotency_keys (scope,principal_type,principal_id,idempotency_key,request_hash,locked_until,created_at,expires_at) VALUES (:scope,:type,:id,:key,:hash,DATE_ADD(UTC_TIMESTAMP(),INTERVAL 2 MINUTE),UTC_TIMESTAMP(),DATE_ADD(UTC_TIMESTAMP(),INTERVAL 24 HOUR))');$stmt->execute(['scope'=>$scope,'type'=>$principal['type'],'id'=>$principal['id'],'key'=>$key,'hash'=>$hash]);return ['id'=>(int)$db->lastInsertId(),'replayed'=>false];}
    catch(PDOException $e){if((string)$e->getCode()!=='23000')throw $e;$stmt=$db->prepare('SELECT * FROM idempotency_keys WHERE scope=:scope AND principal_type=:type AND principal_id=:id AND idempotency_key=:key LIMIT 1');$stmt->execute(['scope'=>$scope,'type'=>$principal['type'],'id'=>$principal['id'],'key'=>$key]);$row=$stmt->fetch();if(!$row||!hash_equals($row['request_hash'],$hash))json_response(409,['success'=>false,'message'=>'This idempotency key was used for a different request.']);if($row['response_status']!==null)json_response((int)$row['response_status'],json_decode((string)$row['response_json'],true)?:[]);json_response(409,['success'=>false,'message'=>'An identical request is already being processed.']);}
}
function finish_idempotent_request(int $id,int $status,array $response): void {get_db()->prepare('UPDATE idempotency_keys SET response_status=:status,response_json=:response,locked_until=NULL WHERE id=:id')->execute(['status'=>$status,'response'=>json_encode($response,JSON_UNESCAPED_SLASHES|JSON_UNESCAPED_UNICODE),'id'=>$id]);}
